package vn.vinhkhang.warehouse;
import java.util.*;import java.math.BigDecimal;import java.time.LocalDate;import java.time.format.DateTimeParseException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.http.ResponseEntity;import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api") public class SalesShipments {
 private final Api core;private final JdbcTemplate db;
 public SalesShipments(Api core,JdbcTemplate db){this.core=core;this.db=db;}
 static String optional(Map<String,Object> m,String k,int max){String s=Objects.toString(m.get(k),"").trim();if(s.length()>max)throw new Api.Problem(400,"Thông tin quá dài: "+k);return s;}
 static LocalDate date(Map<String,Object> m){try{return LocalDate.parse(Objects.toString(m.getOrDefault("shipment_date",LocalDate.now().toString())));}catch(DateTimeParseException e){throw new Api.Problem(400,"Ngày xuất không hợp lệ");}}
 static int requested(Map<String,Object> v){try{int n=Integer.parseInt(Objects.toString(v.getOrDefault("requested_quantity",1)));if(n<1||n>100000)throw new NumberFormatException();return n;}catch(NumberFormatException e){throw new Api.Problem(400,"Số lượng yêu cầu phải là số nguyên từ 1 đến 100000");}}
 static BigDecimal price(Map<String,Object> v){String s=Objects.toString(v.get("unit_price"),"").trim();if(s.isEmpty())return null;try{BigDecimal p=new BigDecimal(s);if(p.signum()<0||p.scale()>2||p.precision()>16)throw new NumberFormatException();return p;}catch(NumberFormatException e){throw new Api.Problem(400,"Đơn giá phải không âm, tối đa 2 chữ số thập phân");}}
 static String purpose(Map<String,Object> m){String p=Objects.toString(m.get("shipment_purpose"),"SALE");if(!Set.of("SALE","INTERNAL","CONSIGNMENT","RETURN").contains(p))throw new Api.Problem(400,"Loại xuất hàng không hợp lệ");return p;}
 static void validate(Api core,Map<String,Object> m){date(m);purpose(m);VehicleTypes.type(m);Set<Long> ids=new HashSet<>();for(var v:core.lines(m,"vehicles")){if(!ids.add(core.num(v,"id")))throw new Api.Problem(400,"Xe bị chọn trùng");requested(v);optional(v,"color",60);if(purpose(m).equals("SALE")&&price(v)==null)throw new Api.Problem(400,"Nhập giá bán xe trước khi xuất");}for(String k:List.of("phone","address","reason","accessories","delivery_person","recipient","warehouse_keeper"))optional(m,k,k.equals("phone")?100:List.of("delivery_person","recipient","warehouse_keeper").contains(k)?200:500);}
 static void persist(JdbcTemplate db,Api core,long id,Map<String,Object> m){
 db.update("UPDATE vehicle_shipments SET vehicle_type=?,shipment_date=?,phone=?,address=?,reason=?,accessories=?,delivery_person=?,recipient=?,warehouse_keeper=? WHERE id=?",VehicleTypes.type(m),date(m),optional(m,"phone",100),optional(m,"address",500),optional(m,"reason",500),optional(m,"accessories",500),optional(m,"delivery_person",200),optional(m,"recipient",200),optional(m,"warehouse_keeper",200),id);
 for(var v:core.lines(m,"vehicles")){long vehicle=core.num(v,"id");if(v.containsKey("color")){String color=optional(v,"color",60);var original=db.queryForList("SELECT color,production_line_id FROM vehicles WHERE id=? FOR UPDATE",vehicle).getFirst();if(original.get("PRODUCTION_LINE_ID")!=null&&!color.equals(original.get("COLOR")))throw new Api.Problem(409,"Xe từ lệnh sản xuất giữ màu theo linh kiện đã dùng");db.update("UPDATE vehicles SET color=? WHERE id=?",color,vehicle);}db.update("UPDATE vehicle_shipment_lines SET vehicle_type=?,requested_quantity=?,unit_price=? WHERE shipment_id=? AND vehicle_id=?",VehicleTypes.type(m),requested(v),price(v),id,vehicle);
 db.update("UPDATE vehicle_shipment_lines l SET item_code=COALESCE(item_code,(SELECT m.code FROM vehicles v JOIN vehicle_models m ON m.id=v.model_id WHERE v.id=?)),description=(SELECT m.name || CASE WHEN v.color='' THEN '' ELSE ' - ' || v.color END FROM vehicles v JOIN vehicle_models m ON m.id=v.model_id WHERE v.id=?),frame_number=COALESCE(frame_number,(SELECT frame_number FROM vehicles WHERE id=?)),motor_number=COALESCE(motor_number,(SELECT motor_number FROM vehicles WHERE id=?)) WHERE shipment_id=? AND vehicle_id=?",vehicle,vehicle,vehicle,vehicle,id,vehicle);}}
 static String esc(Object v){return Objects.toString(v,"").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 static String money(Object v){if(v==null)return "";var symbols=new java.text.DecimalFormatSymbols(java.util.Locale.ROOT);symbols.setGroupingSeparator('.');symbols.setDecimalSeparator(',');return new java.text.DecimalFormat("#,##0.##",symbols).format(v);}
 static String dateLabel(Object value){LocalDate d=LocalDate.parse(value.toString());return "Ngày "+String.format("%02d",d.getDayOfMonth())+" tháng "+String.format("%02d",d.getMonthValue())+" năm "+d.getYear();}
 @GetMapping("/shipment-print/{id}") @Transactional(readOnly=true) public Map<String,String> print(@RequestHeader(value="Authorization",required=false) String t,@PathVariable long id){core.user(t,false);var rows=db.queryForList("SELECT * FROM vehicle_shipments WHERE id=? AND deleted=FALSE",id);if(rows.isEmpty())throw new Api.Problem(404,"Phiếu không tồn tại hoặc đã hủy");var s=rows.getFirst();String actual=ShipmentChargers.lines(db,id).stream().map(l->l.get("PART_NAME")+": "+l.get("QUANTITY")+" chiếc").collect(java.util.stream.Collectors.joining("; "));if(!actual.isEmpty())s.put("ACCESSORIES",Objects.toString(s.get("ACCESSORIES"),"")+"\nSạc thực giao: "+actual);var lines=db.queryForList("SELECT * FROM vehicle_shipment_lines WHERE shipment_id=? ORDER BY vehicle_id",id);return Map.of("html",html(s,lines),"code",s.get("CODE").toString());}
 record PrintKey(Object code,Object description,BigDecimal price,Integer separate){}
 record PrintLine(Map<String,Object> item,int quantity,int requested,BigDecimal price){}
 static List<PrintLine> printLines(List<Map<String,Object>> lines){
  Map<PrintKey,PrintLine> grouped=new LinkedHashMap<>();int index=0;
  for(var item:lines){BigDecimal price=(BigDecimal)item.get("UNIT_PRICE");var key=new PrintKey(item.get("ITEM_CODE"),item.get("DESCRIPTION"),price==null?null:price.stripTrailingZeros(),"COMMERCIAL".equals(item.get("VEHICLE_TYPE"))?null:index);index++;
   var previous=grouped.get(key);grouped.put(key,new PrintLine(item,previous==null?1:previous.quantity()+1,((Number)item.get("REQUESTED_QUANTITY")).intValue()+(previous==null?0:previous.requested()),price));
  }return new ArrayList<>(grouped.values());
 }
 static List<PrintLine> noPriceLines(List<Map<String,Object>> lines){
  Map<PrintKey,PrintLine> grouped=new LinkedHashMap<>();int index=0;
  for(var item:lines){var key=new PrintKey(item.get("ITEM_CODE"),item.get("DESCRIPTION"),null,"COMMERCIAL".equals(item.get("VEHICLE_TYPE"))?null:index++);var previous=grouped.get(key);grouped.put(key,new PrintLine(item,previous==null?1:previous.quantity()+1,((Number)item.get("REQUESTED_QUANTITY")).intValue()+(previous==null?0:previous.requested()),null));}return new ArrayList<>(grouped.values());
 }
 static String html(Map<String,Object> s,List<Map<String,Object>> lines){
  StringBuilder rows=new StringBuilder();int index=0,requested=0,actual=0;
  for(var row:noPriceLines(lines)){var l=row.item();requested+=row.requested();actual+=row.quantity();rows.append("<tr><td>").append(++index).append("</td><td>").append(esc(l.get("ITEM_CODE"))).append("</td><td class='description'>").append(esc(l.get("DESCRIPTION"))).append("COMMERCIAL".equals(l.get("VEHICLE_TYPE"))?"<small>Thương Mại</small>":"<small>Số khung: "+esc(l.get("FRAME_NUMBER"))+"<br>Số máy: "+esc(l.get("MOTOR_NUMBER"))+"</small>").append("</td><td>Chiếc</td><td>").append(row.requested()).append("</td><td>").append(row.quantity()).append("</td></tr>");}
  String date=dateLabel(s.get("SHIPMENT_DATE"));String title=switch(Objects.toString(s.get("SHIPMENT_PURPOSE"),"SALE")){case "INTERNAL"->"PHIẾU XUẤT NỘI BỘ";case "CONSIGNMENT"->"PHIẾU XUẤT KÝ GỬI";case "RETURN"->"PHIẾU TRẢ NHÀ CUNG CẤP";default->"PHIẾU XUẤT BÁN HÀNG";};
  return "<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta http-equiv='Content-Security-Policy' content=\"default-src 'none';style-src 'unsafe-inline'\"><title>Phiếu xuất "+esc(s.get("CODE"))+"</title><style>@page{size:A4 portrait;margin:14mm}*{box-sizing:border-box}body{font-family:'Times New Roman',serif;font-size:15px;margin:0;padding:20px}h1{text-align:center;font-size:23px}.center{text-align:center}.date{font-style:italic;font-size:19px}.info{line-height:1.7;overflow-wrap:anywhere;margin-bottom:18px}table{border-collapse:collapse;width:100%;table-layout:fixed}td,th{border:1px solid #000;padding:7px 4px;text-align:center;overflow-wrap:anywhere}thead{display:table-header-group}tr{break-inside:avoid}td.description{text-align:left}small{display:block;font-size:12px;margin-top:5px}.total{font-weight:bold}.accessories{margin:18px 0;white-space:pre-wrap}.signature-date{text-align:right;font-style:italic;margin-top:24px}.signatures{display:flex;gap:10px;text-align:center;break-inside:avoid}.signatures>div{flex:1}.signature-name{margin-top:65px}@media print{body{padding:0}}</style></head><body><h1>"+title+"</h1><p class='center date'>"+date+"</p><p class='center'>Số phiếu: "+esc(s.get("CODE"))+"</p><div class='info'>Người nhận: "+esc(s.get("CUSTOMER"))+(Objects.toString(s.get("PHONE"),"").isBlank()?"":" ("+esc(s.get("PHONE"))+")")+"<br>Địa chỉ nhận: "+esc(s.get("ADDRESS"))+"<br>Lý do xuất kho: "+esc(s.get("REASON"))+"</div><table><colgroup><col style='width:6%'><col style='width:12%'><col style='width:46%'><col style='width:10%'><col style='width:13%'><col style='width:13%'></colgroup><thead><tr><th rowspan='2'>STT</th><th rowspan='2'>Mã VTHH</th><th rowspan='2'>Tên, nhãn hiệu, quy cách, phẩm chất vật tư, dụng cụ sản phẩm</th><th rowspan='2'>Đơn vị tính</th><th colspan='2'>Số lượng</th></tr><tr><th>Yêu cầu</th><th>Thực xuất</th></tr></thead><tbody>"+rows+"<tr class='total'><td colspan='4'>Cộng</td><td>"+requested+"</td><td>"+actual+"</td></tr></tbody></table><div class='accessories'><b><i>Phụ kiện:</i></b><br>"+esc(s.get("ACCESSORIES"))+"</div><p class='signature-date'>"+date+"</p><div class='signatures'><div><b>Người giao hàng</b><p>(Ký, họ tên)</p><div class='signature-name'>"+esc(s.get("DELIVERY_PERSON"))+"</div></div><div><b>Người nhận hàng</b><p>(Ký, họ tên)</p><div class='signature-name'>"+esc(s.get("RECIPIENT"))+"</div></div><div><b>Thủ kho</b><p>(Ký, họ tên)</p><div class='signature-name'>"+esc(s.get("WAREHOUSE_KEEPER"))+"</div></div></div></body></html>";
 }
 @ExceptionHandler(Api.Problem.class) ResponseEntity<?> problem(Api.Problem e){return ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
}
